			@Nullable ElementType type2) {
		if (e1 == null) {
			return -1;
		}
		if (e2 == null) {
			return 1;
		}
		boolean type1Indexed = (type1 != null) && type1.isIndexed();
		boolean type2Indexed = (type2 != null) && type2.isIndexed();
		int result = Boolean.compare(type2Indexed, type1Indexed);
		if (result != 0) {
			return result;
